CREATE TABLE app_users(id varchar(36) PRIMARY KEY,email nvarchar(254) NOT NULL UNIQUE,display_name nvarchar(80) NOT NULL,password_hash varchar(100) NOT NULL,role varchar(16) NOT NULL CHECK(role IN ('MEMBER','REVIEWER','ADMIN')),active bit NOT NULL DEFAULT 1,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE media_files(id varchar(36) PRIMARY KEY,owner_id varchar(36) NOT NULL REFERENCES app_users(id),storage_name varchar(80) NOT NULL UNIQUE,mime_type varchar(64) NOT NULL,size_bytes bigint NOT NULL,sha256 char(64) NOT NULL,duration_seconds float NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE contributions(id varchar(36) PRIMARY KEY,author_id varchar(36) NOT NULL REFERENCES app_users(id),status varchar(24) NOT NULL CHECK(status IN ('DRAFT','SUBMITTED','IN_REVIEW','CHANGES_REQUESTED','APPROVED','REJECTED')),payload nvarchar(max) NOT NULL,media_id varchar(36) NULL REFERENCES media_files(id),reviewer_id varchar(36) NULL REFERENCES app_users(id),version int NOT NULL DEFAULT 0,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),updated_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_contributions_author ON contributions(author_id,updated_at DESC);
CREATE INDEX IX_contributions_queue ON contributions(status,updated_at);
CREATE TABLE published_tips(id varchar(80) PRIMARY KEY,payload nvarchar(max) NOT NULL,media_id varchar(36) NULL REFERENCES media_files(id),contribution_id varchar(36) NULL UNIQUE REFERENCES contributions(id),reviewer_id varchar(36) NULL REFERENCES app_users(id),verification varchar(32) NOT NULL,published_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE review_decisions(id varchar(36) PRIMARY KEY,contribution_id varchar(36) NOT NULL REFERENCES contributions(id),reviewer_id varchar(36) NOT NULL REFERENCES app_users(id),decision varchar(24) NOT NULL,notes nvarchar(2500) NOT NULL,evidence nvarchar(2000) NOT NULL,science_checked bit NOT NULL,safety_checked bit NOT NULL,materials_checked bit NOT NULL,payload_snapshot nvarchar(max) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE bookmarks(user_id varchar(36) NOT NULL REFERENCES app_users(id),tip_id varchar(80) NOT NULL REFERENCES published_tips(id),created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),PRIMARY KEY(user_id,tip_id));
CREATE TABLE learning_progress(user_id varchar(36) NOT NULL REFERENCES app_users(id),tip_id varchar(80) NOT NULL REFERENCES published_tips(id),completed bit NOT NULL,updated_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),PRIMARY KEY(user_id,tip_id));
CREATE TABLE feedback(id varchar(36) PRIMARY KEY,user_id varchar(36) NOT NULL REFERENCES app_users(id),tip_id varchar(80) NOT NULL REFERENCES published_tips(id),body nvarchar(1500) NOT NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE audit_events(id varchar(36) PRIMARY KEY,actor_id varchar(36) NULL,action varchar(60) NOT NULL,target_id varchar(80) NULL,request_id varchar(36) NULL,created_at datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE INDEX IX_audit_created ON audit_events(created_at DESC);
CREATE TABLE rate_buckets(bucket_key char(64) PRIMARY KEY,hits int NOT NULL,expires_at datetime2 NOT NULL);
CREATE TABLE SPRING_SESSION(PRIMARY_ID char(36) NOT NULL PRIMARY KEY,SESSION_ID char(36) NOT NULL,CREATION_TIME bigint NOT NULL,LAST_ACCESS_TIME bigint NOT NULL,MAX_INACTIVE_INTERVAL int NOT NULL,EXPIRY_TIME bigint NOT NULL,PRINCIPAL_NAME nvarchar(100));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES(SESSION_PRIMARY_ID char(36) NOT NULL,ATTRIBUTE_NAME nvarchar(200) NOT NULL,ATTRIBUTE_BYTES varbinary(max) NOT NULL,CONSTRAINT SPRING_SESSION_ATTRIBUTES_PK PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME),CONSTRAINT SPRING_SESSION_ATTRIBUTES_FK FOREIGN KEY(SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE);
